CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_breadth_project_pending_v2(p_limit integer DEFAULT 2)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE p record; v_pages integer:=0;v_rows bigint:=0;v_errors integer:=0;
BEGIN
 FOR p IN SELECT pg.task_id,pg.page_no,pg.run_id FROM astra_ingestion_v1.backfill_pages_v2 pg JOIN astra_ingestion_v1.backfill_tasks_v2 t ON t.id=pg.task_id
  WHERE t.family='D03' AND lower(t.provider)='derived'
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_breadth_projected_pages_v2 q WHERE q.task_id=pg.task_id AND q.page_no=pg.page_no)
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_audit_v2 a WHERE a.task_id=pg.task_id AND a.action='D03_PROJECTION_FAILURE' AND a.evidence->>'page_no'=pg.page_no::text)
  ORDER BY pg.committed_at,pg.task_id,pg.page_no LIMIT GREATEST(1,LEAST(p_limit,8))
 LOOP
  BEGIN v_rows:=v_rows+astra_ingestion_v1.backfill_breadth_project_page_v2(p.task_id,p.page_no);v_pages:=v_pages+1;
  EXCEPTION WHEN OTHERS THEN
   v_errors:=v_errors+1;
   INSERT INTO astra_ingestion_v1.backfill_audit_v2(run_id,task_id,action,evidence) VALUES(p.run_id,p.task_id,'D03_PROJECTION_FAILURE',
    jsonb_build_object('page_no',p.page_no,'sqlstate',SQLSTATE,'reason',left(SQLERRM,500),'next_action','Repair the projection and execute backfill_breadth_project_page_v2 for this exact task/page'));
  END;
 END LOOP;
 RETURN jsonb_build_object('projected_pages',v_pages,'projected_records',v_rows,'projection_errors',v_errors);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_contract_maintain_v2()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '20s'
AS $function$
DECLARE r record;x record;c astra_ingestion_v1.backfill_contract_readback_cursor_v2;n integer:=0;
BEGIN
 FOR r IN SELECT id FROM astra_ingestion_v1.backfill_runs_v2 WHERE status='ACTIVE' ORDER BY created_at LIMIT 1 LOOP
  PERFORM astra_ingestion_v1.backfill_contract_seed_v2(r.id,8);
  FOR x IN SELECT e.task_id,e.page_no FROM astra_ingestion_v1.backfill_contract_enumeration_v2 e JOIN astra_ingestion_v1.backfill_readbacks_v2 b USING(task_id,page_no)
   WHERE e.run_id=r.id AND e.processed_at IS NULL ORDER BY e.task_id,e.page_no LIMIT 1 LOOP PERFORM astra_ingestion_v1.backfill_contract_admit_page_v2(x.task_id,x.page_no);n:=n+1;END LOOP;
 END LOOP;
 SELECT * INTO STRICT c FROM astra_ingestion_v1.backfill_contract_readback_cursor_v2 WHERE singleton FOR UPDATE;
 FOR x IN SELECT b.verified_at,b.task_id,b.page_no,t.kind FROM astra_ingestion_v1.backfill_readbacks_v2 b JOIN astra_ingestion_v1.backfill_tasks_v2 t ON t.id=b.task_id
  WHERE (b.verified_at,b.task_id,b.page_no)>(c.verified_at,c.task_id,c.page_no) ORDER BY b.verified_at,b.task_id,b.page_no LIMIT 32 LOOP
  -- Catchup only queues retained enumeration pointers. Heavy source parsing and
  -- admission stays at one page per maintenance call, never32 provider pages.
  IF x.kind='alpaca_option_contracts' THEN PERFORM astra_ingestion_v1.backfill_contract_enqueue_v2(x.task_id,x.page_no);
  ELSIF x.kind='alpaca_option_bars' THEN PERFORM astra_ingestion_v1.backfill_contract_register_child_v2(x.task_id);END IF;
  UPDATE astra_ingestion_v1.backfill_contract_readback_cursor_v2 SET verified_at=x.verified_at,task_id=x.task_id,page_no=x.page_no WHERE singleton;
 END LOOP;RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_discover_pending_v2()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x record;
BEGIN
 SELECT d.run_id,d.member_id INTO x FROM astra_ingestion_v1.backfill_identity_discovered_members_v2 d
 JOIN astra_ingestion_v1.backfill_runs_v2 r ON r.id=d.run_id WHERE NOT d.complete AND r.status='ACTIVE'
 ORDER BY d.observed_at,d.run_id,d.member_id LIMIT 1;
 IF NOT FOUND THEN RETURN 0; END IF;
 RETURN astra_ingestion_v1.backfill_identity_discover_member_v2(x.run_id,x.member_id);
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_identity_refresh_pending_v2(p_limit integer DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
 SET statement_timeout TO '8s'
AS $function$
DECLARE q astra_ingestion_v1.backfill_identity_refresh_v2;t astra_ingestion_v1.backfill_tasks_v2;v jsonb;v_id text;n integer:=0;seen integer:=0;last_id text;
BEGIN
 SELECT x.* INTO q FROM astra_ingestion_v1.backfill_identity_refresh_v2 x JOIN astra_ingestion_v1.backfill_runs_v2 r ON r.id=x.run_id
  WHERE r.status='ACTIVE' AND x.ready_after<=clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_source_members_v2 sm JOIN astra_ingestion_v1.backfill_tasks_v2 st ON st.id=sm.task_id
    WHERE sm.run_id=x.run_id AND sm.member_id=x.member_id AND st.status IN('PENDING','RUNNING','RETRY_WAIT'))
  ORDER BY x.ready_after,x.run_id,x.member_id LIMIT 1 FOR UPDATE OF x;
 IF NOT FOUND THEN RETURN 0; END IF;
 PERFORM 1 FROM astra_ingestion_v1.backfill_runs_v2 WHERE id=q.run_id AND status='ACTIVE' FOR UPDATE;
 IF NOT FOUND THEN RETURN 0; END IF;
 last_id:=q.after_task_id;
 FOR t IN SELECT * FROM astra_ingestion_v1.backfill_tasks_v2 z WHERE z.run_id=q.run_id AND z.id>q.after_task_id AND NOT(z.scope ? 'identity_refresh_of')
  AND ((q.member_id='__COHORT__' AND z.kind='derive_breadth') OR (z.kind='derive_daily' AND z.scope#>>'{member_ids,0}'=q.member_id))
  AND z.status IN('INGESTED','NO_DATA_RETURNED','IDENTITY_OR_QUALITY_UNRESOLVED')
  AND COALESCE((z.scope->>'input_start')::date,(z.scope->>'target_start')::date)<=q.latest_date
  AND (z.scope->>'target_end')::date>=q.earliest_date ORDER BY z.id LIMIT GREATEST(1,LEAST(p_limit,8))
 LOOP
  seen:=seen+1;last_id:=t.id;v:=astra_ingestion_v1.backfill_identity_build_material_v2(t);
  INSERT INTO astra_ingestion_v1.backfill_identity_roots_v2(root_task_id,run_id,member_id,input_start,target_end,identity_material_sha256)
  VALUES(t.id,t.run_id,CASE WHEN t.kind<>'derive_breadth' THEN q.member_id END,COALESCE((t.scope->>'input_start')::date,(t.scope->>'target_start')::date),(t.scope->>'target_end')::date,v->>'identity_material_sha256')
  ON CONFLICT(root_task_id) DO UPDATE SET identity_material_sha256=EXCLUDED.identity_material_sha256,invalidated=false,checked_at=clock_timestamp();
  IF EXISTS(SELECT 1 FROM astra_ingestion_v1.backfill_identity_calculation_receipts_v2 c
    WHERE c.root_task_id=t.id AND c.identity_material_sha256=v->>'identity_material_sha256') THEN CONTINUE; END IF;
  v_id:='backfill-identity-refresh-'||encode(sha256(convert_to(t.id||':'||(v->>'identity_material_sha256'),'UTF8')),'hex');
  INSERT INTO astra_ingestion_v1.backfill_tasks_v2(id,run_id,family,provider,kind,scope,dependencies,priority,run_fence)
  VALUES(v_id,t.run_id,t.family,t.provider,t.kind,t.scope||jsonb_build_object('identity_refresh_of',t.id,
    'identity_material_sha256',v->>'identity_material_sha256','plan_static',false,'prefer_retained_formula_cache',false),t.dependencies,GREATEST(t.priority,150),t.run_fence)
  ON CONFLICT(id) DO NOTHING;
  n:=n+1;
 END LOOP;
 IF seen<GREATEST(1,LEAST(p_limit,8)) THEN DELETE FROM astra_ingestion_v1.backfill_identity_refresh_v2 WHERE run_id=q.run_id AND member_id=q.member_id;
 ELSE UPDATE astra_ingestion_v1.backfill_identity_refresh_v2 SET after_task_id=last_id WHERE run_id=q.run_id AND member_id=q.member_id; END IF;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION astra_ingestion_v1.backfill_nonminute_project_pending_v2(p_limit integer DEFAULT 2)
 RETURNS integer
 LANGUAGE plpgsql
